<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">		next.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ServeHTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(w, r.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WithContext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx))</span></span>
